fn oct_u64(buf: &[u8]) -> Result<u64, i32> {
    let field = buf.split(|b| *b == 0).next().unwrap_or(buf);
    let field = field.strip_prefix(b" ").unwrap_or(field);
    let field = field.strip_suffix(b" ").unwrap_or(field);
    if field.is_empty() || !field.iter().all(|b| matches!(b, b'0'..=b'7')) {
        return Err(1);
    }
    let mut n = 0u64;
    for &b in field {
        n = n.checked_mul(8).and_then(|v| v.checked_add(u64::from(b - b'0'))).ok_or(1)?;
    }
    Ok(n)
}

pub fn scan(path: &str) -> Result<Vec<Row>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    if raw.len() < 1024 || raw.len() % 512 != 0 {
        return Err(1);
    }
    let mut rows = Vec::new();
    let mut off = 0usize;
    let mut ended = false;
    while off + 512 <= raw.len() {
        let blk = &raw[off..off + 512];
        if blk.iter().all(|b| *b == 0) {
            if off + 1024 > raw.len() || !raw[off + 512..off + 1024].iter().all(|b| *b == 0) {
                return Err(1);
            }
            if !raw[off..].iter().all(|b| *b == 0) {
                return Err(1);
            }
            ended = true;
            break;
        }
        if &blk[257..262] != b"ustar" {
            return Err(1);
        }
        let stored_sum = oct_u64(&blk[148..156])?;
        let actual_sum: u64 = blk.iter().enumerate().map(|(i, b)| {
            if (148..156).contains(&i) { 32 } else { u64::from(*b) }
        }).sum();
        if stored_sum != actual_sum {
            return Err(1);
        }
        let nlen = blk[0..100].iter().position(|b| *b == 0).unwrap_or(100);
        if nlen == 0 {
            return Err(1);
        }
        let name = std::str::from_utf8(&blk[0..nlen]).map_err(|_| 1)?.to_string();
        let size = oct_u64(&blk[124..136])?;
        let padded = size.checked_add(511).ok_or(1)? / 512 * 512;
        let next = (off as u64).checked_add(512).and_then(|v| v.checked_add(padded)).ok_or(1)?;
        if next > raw.len() as u64 {
            return Err(1);
        }
        rows.push(Row { name, hdr: off as u64, size, body: (off + 512) as u64, flag: blk[156] });
        off = next as usize;
    }
    if rows.is_empty() || !ended {
        return Err(1);
    }
    Ok(rows)
}

